-- ----------------------------
-- Table structure for t_mt_measuring_point_info
-- ----------------------------
DROP TABLE IF EXISTS `t_mt_measuring_point_info`;
CREATE TABLE `t_mt_measuring_point_info`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '测点信息 ID，自增主键',
  `measuring_point_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '测点名称',
  `x_position` double NULL DEFAULT 0 COMMENT '位置x',
  `y_position` double NULL DEFAULT 0 COMMENT '位置y',
  `z_position` double NULL DEFAULT 0 COMMENT '位置z',
  `x_angle` double NULL DEFAULT 0 COMMENT '角度x',
  `y_angle` double NULL DEFAULT 0 COMMENT '角度y',
  `z_angle` double NULL DEFAULT 0 COMMENT '角度z',
  `coordinate_code` bigint(20) UNSIGNED NULL DEFAULT NULL COMMENT '坐标系代号，预留字段',
  `test_work_condition_id` bigint(20) NULL DEFAULT NULL COMMENT '工况id',
  `node` int(11) NULL DEFAULT NULL COMMENT '仿真数据中的节点号',
  `element` bigint(20) NULL DEFAULT NULL COMMENT '单元节点',
  `sensor_type_id` bigint(20) NULL DEFAULT NULL COMMENT '传感器类型id',
  `base_size_long` double NULL DEFAULT NULL COMMENT '基底尺寸长(h)',
  `base_size_wide` double NULL DEFAULT NULL COMMENT '基底尺寸宽(w)',
  `patch_location` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贴片位置    内表面：N 外表面:Y',
  `is_from_test_data` int(11) NULL DEFAULT 0 COMMENT '是否是从试验数据中获取的测点',
  `data_source` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据来源 SJZT：数据中台  XSPT：虚实平台 LOCAL：本地上传',
  `sensor_model` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '传感器型号',
  `source_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源ID',
  `x_position_ori` double NULL DEFAULT 0 COMMENT '位置x原始',
  `y_position_ori` double NULL DEFAULT 0 COMMENT '位置y原始',
  `z_position_ori` double NULL DEFAULT 0 COMMENT '位置z原始',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '工程ID',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '修改人',
  `extra_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仿真数据',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11952 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '力学试验-测点信息表' ROW_FORMAT = Dynamic;

